(()=>{const f=document.querySelector("#adverseForm"),details=document.querySelector("#eventDetails"),otherCheck=document.querySelector("#adverseOtherCheck"),otherText=document.querySelector("#adverseOtherText");
/* 选择“有”才填写不良反应明细；勾选“其他”才填写其他不良反应 */
function sync(){const v=f.querySelector('input[name="hasAdverseEvent"]:checked')?.value;const hide=v!=="有";details.classList.toggle("is-hidden",hide);details.querySelectorAll("input,textarea").forEach(x=>x.disabled=hide);const showOther=!hide&&otherCheck.checked;otherText.classList.toggle("is-hidden",!showOther);otherText.disabled=!showOther;if(!otherCheck.checked)otherText.value=""}
f.querySelectorAll('input[name="hasAdverseEvent"]').forEach(x=>x.onchange=sync);otherCheck.addEventListener("change",sync);
f.onsubmit=e=>{e.preventDefault();const fd=new FormData(f),data={};for(const [k,v] of fd){if(k==="adverseEvents"){(data[k]??=[]).push(v)}else data[k]=v}const payload={type:"adverse-reaction",data};if(window.webkit?.messageHandlers?.saveForm)window.webkit.messageHandlers.saveForm.postMessage(payload);else if(window.Android&&typeof window.Android.saveForm==="function")window.Android.saveForm(JSON.stringify(payload));else{console.log("[ADVERSE REACTION]",payload);history.back()}};sync()})();
